"""Generate fixtures with `scipy.special.log1p` on the shared inputs in `../../inputs/`."""

import os
import sys
import json
import hashlib
import math
import platform
from datetime import datetime, timezone
import numpy as np
import scipy
from scipy.special import log1p

# Get the file path:
FILE = os.path.realpath(__file__)

# Extract the directory in which this file resides:
DIR = os.path.dirname(FILE)

# Shared inputs:
INPUTS = os.path.join(DIR, "..", "..", "inputs")

SPECIAL = {
    "NaN": float("nan"),
    "Infinity": float("inf"),
    "-Infinity": float("-inf"),
}


def decode(v):
    """Decode a JSON value from a shared input file as a double."""
    if isinstance(v, str):
        return SPECIAL[v]
    return float(v)


def encode(x):
    """Encode a double as a JSON value, matching the shared input files."""
    if x is None:
        return "null"
    if math.isnan(x):
        return '"NaN"'
    if x == float("inf"):
        return '"Infinity"'
    if x == float("-inf"):
        return '"-Infinity"'
    return repr(x)  # shortest round-trip decimal


def libc():
    """Return the C library's name and version."""
    name, version = platform.libc_ver()
    if name:
        return name + " " + version
    return None


def evaluate(x):
    """Evaluate `log1p` over a list of doubles.

    SciPy returns NaN or infinity rather than raising, so no errors are recorded.
    """
    y = log1p(np.array(x, dtype=np.float64))
    return [float(v) for v in y], [None] * len(x)


def gen(name):
    """Read the shared input file `name`, and write fixtures to a file of the same name.

    # Arguments

    * `name::str`: input and output filename
    """
    with open(os.path.join(INPUTS, name), "rb") as infile:
        raw = infile.read()
    data = json.loads(raw.decode("utf-8"))
    x = [decode(v) for v in data["x"]]
    y, errors = evaluate(x)

    meta = {
        "source": "python::scipy",
        "function": "scipy.special.log1p",
        "implementation": "xsf, from Cephes (unity.c); log(1+x) through the C library outside sqrt(1/2) < 1+x < sqrt(2)",
        "versions": {
            "python": platform.python_version(),
            "scipy": scipy.__version__,
            "numpy": np.__version__
        },
        "platform": {
            "os": sys.platform,
            "arch": platform.machine(),
            "compiler": None,
            "libc": libc()
        },
        "generated": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        "inputs": hashlib.sha256(raw).hexdigest(),
        "regime": data["regime"]
    }

    out = '{"x":[' + ",".join(encode(v) for v in x) + "]"
    out += ',"expected":[' + ",".join(encode(v) for v in y) + "]"
    if any(e is not None for e in errors):
        out += ',"errors":' + json.dumps(errors, separators=(",", ":"))
    out += ',"meta":' + json.dumps(meta, separators=(",", ":")) + "}\n"

    # Write the data to the output filepath as JSON:
    with open(os.path.join(DIR, name), "w", encoding="utf-8") as outfile:
        outfile.write(out)


def main():
    """Generate fixture data."""
    for name in sorted(os.listdir(INPUTS)):
        if name.endswith(".json"):
            gen(name)


if __name__ == "__main__":
    main()
